inputs:
  deck_title:
    description: "幻灯片主标题（免 LLM 直接验证 SVG/PNG 课件渲染与预览）"
    default: "Rust Trait 分发机制可视化"
  slide_theme:
    description: "配色主题：dark 或 light"
